import java.time.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int m = sc.nextInt();
        Instant[] targets = new Instant[m];
        for (int i = 0; i < m; i++) {
            targets[i] = Instant.parse(sc.next());
        }
        int n = sc.nextInt();
        Instant[] times = new Instant[n];
        String[] names = new String[n];
        for (int i = 0; i < n; i++) {
            times[i] = Instant.parse(sc.next());
            names[i] = sc.next();
        }
        for (Instant target : targets) {
            int best = -1;
            for (int i = 0; i < n; i++) {
                if (!times[i].isAfter(target) && (best < 0 || times[i].isAfter(times[best]))) {
                    best = i;
                }
            }
            if (best < 0) {
                System.out.println("previous=NONE");
            } else {
                System.out.println("previous=" + names[best]
                        + " elapsedSeconds=" + Duration.between(times[best], target).toSeconds());
            }
        }
    }
}

