            calls++;
            if (outcome.equals("OK")) {
                result = "ok";
                break;
            }
            if (outcome.equals("P")) {
                result = "order_not_found";
                break;
            }
        }
        System.out.println("calls=" + calls + " result=" + result);
    }
}

