import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        List<String> before = readLine(sc);
        List<String> after = readLine(sc);
        List<String> required = readLine(sc);

        List<String> removed = new ArrayList<>();
        for (String name : before) {
            if (!after.contains(name)) {
                removed.add(name);
            }
        }
        List<String> newRequired = new ArrayList<>();
        for (String name : required) {
            if (!before.contains(name)) {
                newRequired.add(name);
            }
        }
        System.out.println("removed=" + join(removed));
        System.out.println("newRequired=" + join(newRequired));
        System.out.println("breaking=" + !(removed.isEmpty() && newRequired.isEmpty()));
    }

    static List<String> readLine(Scanner sc) {
        String line = sc.hasNextLine() ? sc.nextLine().trim() : "";
        if (line.isEmpty()) {
            return new ArrayList<>();
        }
        return new ArrayList<>(Arrays.asList(line.split("\\s+")));
    }

    static String join(List<String> names) {
        return names.isEmpty() ? "NONE" : String.join(",", names);
    }
}
